draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // body
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // soul
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 70 - 20 * Math.sin(t), 30, 0, 2 * Math.PI);
  ctx.stroke();

  // connection
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 - 70 - 20 * Math.sin(t));
  ctx.stroke();

  // avicenna
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Avicenna', W/2, 20);

  // medicine
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'bottom';
  ctx.fillStyle = 'black';
  ctx.fillText('Medicine', W/2, H - 20);

  // soul body connection
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Soul & Body', W/2, H/2 - 100 - 10 * Math.sin(t));
  ctx.restore();
}
